#!/usr/bin/env bash
# Copies Listmonk's admin login (generated by `make env` into infra/compose/.env) to
# OpenBao at kv/hq/newsletter/admin (keys `user`, `password`), so the owner can read it
# there. Run by `make newsletter-on`. The values are never printed and never put in argv.
set -euo pipefail

REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
ENV_FILE="${HQ_ENV_FILE:-$REPO_DIR/infra/compose/.env}"
SECRETS_DIR="${HQ_SECRETS_DIR:-/home/Hub/.secrets}"
ADMIN_FILE="$SECRETS_DIR/openbao-admin.token"
BAO_ADDR="${HQ_BAO_ADDR:-http://127.0.0.1:8200}"

die() { printf 'newsletter-seed-admin: %s\n' "$*" >&2; exit 1; }

[[ -r "$ENV_FILE" ]] || die "$ENV_FILE is missing (make env)"
[[ -s "$ADMIN_FILE" ]] || die "no OpenBao admin token yet; run 'make up' first"
user="$(sed -n 's/^LISTMONK_ADMIN_USER=//p' "$ENV_FILE" | tail -n1)"
pass="$(sed -n 's/^LISTMONK_ADMIN_PASSWORD=//p' "$ENV_FILE" | tail -n1)"
[[ -n "$pass" ]] || die "LISTMONK_ADMIN_PASSWORD is empty (make env)"

umask 077
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
printf 'X-Vault-Token: %s\n' "$(cat "$ADMIN_FILE")" >"$work/auth"
code="$(U="${user:-hq-admin}" P="$pass" jq -n '{data: {user: env.U, password: env.P}}' |
  curl -sS -o /dev/null -w '%{http_code}' -H @"$work/auth" -H 'Content-Type: application/json' \
    --data-binary @- "$BAO_ADDR/v1/kv/data/hq/newsletter/admin")"
unset pass
[[ "$code" == 200 || "$code" == 204 ]] || die "OpenBao refused the write (HTTP $code)"
echo "Saved Listmonk's admin login in OpenBao (kv/hq/newsletter/admin; values not shown)."
